const jwt = require('jsonwebtoken');

// === CONFIG: same Usersnap surveys as the daily job ===
const SURVEYS = [
  { project_id: 'REPLACE_PROJECT_ID_1', survey_name: 'Web feedback survey' }
];

// Backfill window (days). Edit here to change how far back to load.
const DAYS = 60;

const secret = $env.USERSNAP_TOKEN;
const kid = $env.USERSNAP_JWT_KID;
if (!secret || !kid) {
  throw new Error('Missing env vars: USERSNAP_TOKEN and/or USERSNAP_JWT_KID');
}

const now = Math.floor(Date.now() / 1000);
const token = jwt.sign(
  { iat: now, exp: now + 3600 },
  secret,
  { algorithm: 'HS256', header: { alg: 'HS256', kid: kid, typ: 'JWT' } }
);

const since = new Date(Date.now() - DAYS * 864e5).toISOString();

return SURVEYS.map(s => ({ json: {
  project_id: s.project_id, survey_name: s.survey_name, token, since,
} }));

// Explicit cursor pagination: keep calling the API WHILE has_more is true.
// (Replaces n8n's built-in HTTP pagination, which does not reliably advance the
//  cursor for this POST /feedbacks/filter endpoint.)
// Runs once for all items; input = one item per project from "Backfill Config + JWT".
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const { project_id, token, since } = inputs[i].json;
  const base = `https://platform.usersnap.com/v0.1/projects/${project_id}/feedbacks/filter`;
  const body = {
    query: [{ filter_type: 'created_at', operator: 'gte', value: since }],
    order_by: { order_by_type: 'created_at', direction: 'asc' },
  };

  let after = null;
  let hasMore = true;
  let guard = 0;               // safety cap: 500 pages * 100 = 50k rows max

  while (hasMore && guard < 500) {
    guard++;

    let url = `${base}?limit=100`;
    if (after) url += `&after=${encodeURIComponent(after)}`;

    const res = await this.helpers.httpRequest({
      method: 'POST',
      url,
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body,
      json: true,
    });

    // Response may be array-wrapped [{status,data:{...}}] or a bare {status,data:{...}}.
    const data = Array.isArray(res) ? (res[0] && res[0].data) : (res && res.data);
    const feedbacks = (data && Array.isArray(data.feedbacks)) ? data.feedbacks : [];
    for (const fb of feedbacks) out.push({ json: fb, pairedItem: { item: i } });

    // has_more drives the next loop run; stop when false or no cursor.
    hasMore = !!(data && data.has_more);
    after = (data && data.next) ? data.next.after : null;
    if (!after) hasMore = false;
  }
}

return out;

// Flatten Usersnap feedbacks -> one item per feedback (PII-safe, generic).
// survey_name is resolved by PROJECT_ID (robust; no pairedItem dependency).
const surveys = $('Backfill Config + JWT').all();
const byProject = {};
for (const s of surveys) {
  const j = s.json || {};
  if (j.project_id != null) byProject[String(j.project_id)] = (j.survey_name ?? null);
}

function extractFeedbacks(body) {
  if (Array.isArray(body)) {
    let acc = [];
    for (const el of body) acc = acc.concat(extractFeedbacks(el));
    return acc;
  }
  if (body && typeof body === 'object') {
    if (Array.isArray(body.feedbacks)) return body.feedbacks;
    if (body.data) return extractFeedbacks(body.data);
    if (body.feedback_id) return [body];
  }
  return [];
}

const out = [];
for (const item of $input.all()) {
  const list = extractFeedbacks(item.json);
  for (const fb of list) {
    const inputs = Array.isArray(fb.ordered_inputs) ? fb.ordered_inputs : [];

    const ratingField = inputs.find(i => String(i.field_type || '').startsWith('rating'));
    const rating = ratingField ? (ratingField.numeric_value ?? ratingField.value ?? null) : null;

    const feedback_text = inputs
      .map(i => (i.text_value != null ? String(i.text_value) : ''))
      .filter(t => t.trim() !== '')
      .join('\n');

    const questions = inputs.map(i => ({
      field_id: i.field_id ?? null,
      label: i.label ?? null,
      field_type: i.field_type ?? null,
      value: i.value ?? null,
      order: i.order ?? null,
    }));

    const client = fb.client || {};
    const customData = fb.custom_data || {};

    // PII: never store email. Scrub it from the retained raw payload too.
    const scrubbed = { ...fb };
    delete scrubbed.email;

    const projectId = fb.project_id ?? null;
    out.push({ json: {
      project_id: projectId,
      survey_name: (projectId != null ? (byProject[String(projectId)] ?? null) : null),
      feedback_id: String(fb.feedback_id ?? fb.id ?? ''),
      feedback_number: fb.feedback_number ?? null,
      public_link: fb.public_link ?? null,
      created_at: fb.created_at || null,
      updated_at: fb.updated_at || null,
      status: fb.status_type || fb.status || null,
      country: client.country_name ?? null,
      city: client.city_name ?? null,
      browser: client.browser_full_name ?? null,
      os: client.browser_os ?? null,
      page_url: client.url ?? null,
      app_version: (customData && customData.version) ? customData.version : null,
      rating,
      feedback_text: feedback_text || null,
      questions: JSON.stringify(questions),
      labels: fb.labels ? JSON.stringify(fb.labels) : null,
      raw_payload: JSON.stringify(scrubbed),
    } });
  }
}
return out;

